const j = $input.first().json;
const st = {
  tierIdx: 0, tierTries: 0, softened: 0, blockRetried: false, polls: 0, pollErrors: 0, dlTries: 0, dropImages: false,
  errors: [], attempts: 0, waitSec: j.needsRender ? Math.max(1, j.cfg.scenePaceSec || 8) : 1, opName: null, pollStart: 0, videoUri: null
};
return [{ json: { ...j, st } }];

const fs = require('fs');
const j = $input.first().json;
const st = { ...j.st };
const base = { ...j };
['submit', 'mode', 'route', 'result', 'tier'].forEach((k) => delete base[k]);
if (!j.needsRender) return [{ json: { ...base, st, mode: 'cached' } }];
const tier = j.tiers[st.tierIdx];
if (!tier || st.attempts > 40) return [{ json: { ...base, st, mode: 'fail' } }];
if (tier.model === 'still') return [{ json: { ...base, st, tier, mode: 'still' } }];

st.attempts++;
const ord = { '720p': 1, '1080p': 2, '4k': 3 };
let res = j.resolution;
if (ord[res] > ord[tier.maxRes]) res = tier.maxRes;
const prompt = (st.softened > 0 && j.scene.safeVisualPrompt) ? j.scene.safeVisualPrompt : j.scene.visualPrompt;
const paths = st.dropImages ? [] : (j.imagePaths || []);
const useRefs = j.imageMode === 'reference' && tier.supportsRefs && paths.length > 0;
const useFirst = !useRefs && paths.length > 0 && (j.imageMode === 'first_frame' || (j.imageMode === 'reference' && !tier.supportsRefs));
let d = j.scene.durationSec;
if (useRefs || res !== '720p') d = 8;
const img = (p) => {
  const ext = p.split('.').pop().toLowerCase();
  const mime = ext === 'png' ? 'image/png' : ext === 'webp' ? 'image/webp' : 'image/jpeg';
  return { inlineData: { mimeType: mime, data: fs.readFileSync(p).toString('base64') } };
};
const inst = { prompt };
if (useRefs) inst.referenceImages = paths.slice(0, 3).map((p) => ({ image: img(p), referenceType: 'asset' }));
else if (useFirst) inst.image = img(paths[0]);
const body = { instances: [inst], parameters: { aspectRatio: j.aspectRatio, resolution: res, durationSeconds: d } };
return [{ json: { ...base, st, tier, mode: 'veo', submit: { url: 'https://generativelanguage.googleapis.com/v1beta/models/' + tier.model + ':predictLongRunning', body } } }];

const prev = $('Plan Attempt').first().json;
const r = $input.first().json || {};
const st = { ...prev.st };
const cfg = prev.cfg;
const base = { ...prev };
['submit', 'mode'].forEach((k) => delete base[k]);
const code = Number(r.statusCode) || 0;
const body = r.body && typeof r.body === 'object' ? r.body : {};
const msg = String((body.error && (body.error.message || body.error.status)) || r.error || r.statusMessage || '').slice(0, 300);
const hint = (() => {
  try {
    const d = (body.error && body.error.details) || [];
    for (const x of d) if (x.retryDelay) { const m = String(x.retryDelay).match(/([\d.]+)s/); if (m) return Math.min(60, parseFloat(m[1])); }
  } catch (e) { /* ignore */ }
  const ra = r.headers && (r.headers['retry-after'] || r.headers['Retry-After']);
  return ra ? Math.min(60, parseFloat(ra) || 0) : 0;
})();
const backoff = (n) => Math.min(cfg.backoffMaxSec, Math.max(hint, cfg.backoffBaseSec * Math.pow(2, Math.max(0, n - 1)))) * (0.8 + Math.random() * 0.4);
const log = (w) => st.errors.push('tier' + st.tierIdx + ' (' + (prev.tier && prev.tier.model) + ') ' + w + (msg ? ': ' + msg : ''));
const nextTier = (w) => { log(w + ' -> next tier'); st.tierIdx++; st.tierTries = 0; st.dropImages = false; st.blockRetried = false; st.waitSec = 3; return 'replan'; };
const retrySame = (w) => { log(w + ' -> retry'); st.tierTries++; if (st.tierTries > cfg.maxSubmitRetriesPerTier) return nextTier('retries exhausted'); st.waitSec = Math.max(1, Math.round(backoff(st.tierTries))); return 'replan'; };
const safety = /safety|blocked|violat|prohibit|sensitive|filter|policy|responsible ai|celebrit|minor|child/i.test(msg);
let route;
if (code >= 200 && code < 300 && body.name) { st.opName = body.name; st.polls = 0; st.pollErrors = 0; st.dlTries = 0; st.pollStart = Date.now(); st.waitSec = cfg.pollIntervalSec; route = 'poll'; }
else if (code === 429) route = retrySame('rate limited (429)');
else if (code >= 500 || code === 0) route = retrySame('server/network error ' + code);
else if (code === 401 || (code === 403 && /api key|api_key/i.test(msg))) { log('authentication failed - cannot continue'); st.tierIdx = 999; route = 'replan'; }
else if (code === 404 || code === 403) route = nextTier('model unavailable (' + code + ')');
else if (code === 400) {
  if (safety && st.softened < cfg.maxPromptSoftenings && prev.scene.safeVisualPrompt) { log('blocked by safety -> softened prompt'); st.softened++; st.waitSec = 3; route = 'replan'; }
  else if (safety) route = nextTier('blocked by safety');
  else if ((prev.imagePaths || []).length && !st.dropImages) { log('bad request -> retry without images'); st.dropImages = true; st.waitSec = 3; route = 'replan'; }
  else route = nextTier('bad request');
} else route = nextTier('unexpected status ' + code);
return [{ json: { ...base, st, route } }];

const prev = $('Poll Wait').first().json;
const r = $input.first().json || {};
const st = { ...prev.st };
const cfg = prev.cfg;
const base = { ...prev };
delete base.route;
const code = Number(r.statusCode) || 0;
const b = r.body && typeof r.body === 'object' ? r.body : {};
const msg = String((b.error && (b.error.message || b.error.status)) || r.error || '').slice(0, 300);
const log = (w) => st.errors.push('tier' + st.tierIdx + ' (' + (prev.tier && prev.tier.model) + ') ' + w + (msg ? ': ' + msg : ''));
const backoff = (n) => Math.min(cfg.backoffMaxSec, cfg.backoffBaseSec * Math.pow(2, Math.max(0, n - 1))) * (0.8 + Math.random() * 0.4);
const nextTier = (w) => { log(w + ' -> next tier'); st.tierIdx++; st.tierTries = 0; st.dropImages = false; st.blockRetried = false; st.waitSec = 3; return 'replan'; };
const retrySame = (w) => { log(w + ' -> retry'); st.tierTries++; if (st.tierTries > cfg.maxSubmitRetriesPerTier) return nextTier('retries exhausted'); st.waitSec = Math.max(1, Math.round(backoff(st.tierTries))); return 'replan'; };
const blocked = (w) => {
  if (!st.blockRetried) { st.blockRetried = true; log(w + ' -> one plain retry'); st.waitSec = 3; return 'replan'; }
  if (st.softened < cfg.maxPromptSoftenings && prev.scene.safeVisualPrompt) { log(w + ' -> softened prompt'); st.softened++; st.waitSec = 3; return 'replan'; }
  return nextTier(w);
};
st.polls++;
let route;
if (code === 200 && b.done) {
  if (b.error) {
    const em = String(b.error.message || '') + ' ' + String(b.error.status || '');
    if (/safety|blocked|violat|prohibit|sensitive|filter|policy|audio/i.test(em)) route = blocked('operation blocked');
    else if (/resource_exhausted|quota|rate/i.test(em) || b.error.code === 8 || b.error.code === 429) route = retrySame('operation rate limited');
    else route = retrySame('operation failed');
  } else {
    const resp = b.response && (b.response.generateVideoResponse || b.response);
    const sample = resp && resp.generatedSamples && resp.generatedSamples[0];
    const uri = sample && sample.video && sample.video.uri;
    if (uri) { st.videoUri = uri; route = 'download'; }
    else route = blocked('no video returned (filtered: ' + JSON.stringify((resp && resp.raiMediaFilteredReasons) || []).slice(0, 120) + ')');
  }
} else if (code === 200) {
  if (Date.now() - st.pollStart > cfg.maxPollMinutes * 60000) route = nextTier('poll timeout');
  else { st.waitSec = Math.min(30, cfg.pollIntervalSec + Math.floor(st.polls / 6) * 5); route = 'poll'; }
} else if (code === 404) route = retrySame('operation not found');
else if (code === 429 || code >= 500 || code === 0) {
  st.pollErrors++;
  if (st.pollErrors > 8) route = nextTier('polling kept failing');
  else { st.waitSec = Math.min(60, cfg.pollIntervalSec * 2); route = 'poll'; }
} else route = nextTier('poll error ' + code);
return [{ json: { ...base, st, route } }];

const fs = require('fs');
const prev = $('After Poll').first().json;
const st = { ...prev.st };
const cfg = prev.cfg;
const base = { ...prev };
delete base.route;
const r = $input.first();
const code = Number((r.json || {}).statusCode) || 0;
let saved = false;
if (code === 200 && r.binary && r.binary.data) {
  const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
  if (buf.length > 20000 && buf.subarray(4, 8).toString('latin1') === 'ftyp') {
    fs.mkdirSync(prev.jobDir + '/clips', { recursive: true });
    fs.writeFileSync(prev.outPath, buf);
    saved = true;
  }
}
if (saved) {
  return [{ json: { ...base, st, route: 'done', result: { status: 'ok', sceneIndex: prev.sceneIndex, clipPath: prev.outPath, source: 'veo', model: prev.tier && prev.tier.model, attempts: st.attempts, errors: st.errors } } }];
}
st.dlTries++;
st.errors.push('download failed (status ' + code + ') try ' + st.dlTries);
if (st.dlTries <= 3) { st.waitSec = 10; return [{ json: { ...base, st, route: 'poll' } }]; }
st.tierIdx++; st.tierTries = 0; st.dlTries = 0; st.waitSec = 3;
return [{ json: { ...base, st, route: 'replan' } }];

const j = $input.first().json;
const m = j.cachedMeta || {};
return [{ json: { status: 'cached', sceneIndex: j.sceneIndex, clipPath: j.cachedPath, source: m.source || 'veo', model: m.model || '', attempts: 0, errors: [] } }];

const j = $input.first().json;
const prompt = 'Create ONE cinematic still frame for a video scene, aspect ratio ' + j.aspectRatio + ', no text, no watermark. Scene: ' + j.scene.visualPrompt.replace(/"[^"]*"/g, '').slice(0, 1500);
const reqBody = { contents: [{ role: 'user', parts: [{ text: prompt }] }], generationConfig: { responseModalities: ['IMAGE'] } };
return [{ json: { ...j, imgModel: j.cfg.imageModel, reqBody } }];

const fs = require('fs');
const req = $('Still Request').first().json;
const r = $input.first().json || {};
const base = { ...req };
delete base.reqBody; delete base.imgModel;
try {
  const parts = r.candidates[0].content.parts || [];
  const p = parts.find((x) => x.inlineData || x.inline_data);
  const d = p.inlineData || p.inline_data;
  const dir = base.jobDir + '/work';
  fs.mkdirSync(dir, { recursive: true });
  const img = dir + '/still_' + base.sceneIndex + '.png';
  fs.writeFileSync(img, Buffer.from(d.data, 'base64'));
  const dims = { '720p': [1280, 720], '1080p': [1920, 1080], '4k': [3840, 2160] }[base.resolution] || [1280, 720];
  const vertical = base.aspectRatio === '9:16';
  const W = vertical ? dims[1] : dims[0], H = vertical ? dims[0] : dims[1];
  const fps = base.cfg.fps || 24, secs = base.scene.durationSec, frames = secs * fps;
  const vf = "scale=" + (W * 2) + ":" + (H * 2) + ":force_original_aspect_ratio=increase,crop=" + (W * 2) + ":" + (H * 2) + ",zoompan=z='min(zoom+0.0007,1.12)':x='iw/2-(iw/zoom/2)':y='ih/2-(ih/zoom/2)':d=" + frames + ":s=" + W + "x" + H + ":fps=" + fps + ",format=yuv420p";
  const cmd = 'ffmpeg -hide_banner -loglevel error -y -i "' + img + '" -f lavfi -i anullsrc=r=48000:cl=stereo -vf "' + vf + '" -t ' + secs + ' -shortest -c:v libx264 -preset veryfast -crf 20 -c:a aac -b:a 128k -ar 48000 -ac 2 "' + base.outPath + '"';
  return [{ json: { ...base, ok: true, cmd } }];
} catch (e) {
  return [{ json: { ...base, ok: false, cmd: 'true', stillError: 'still image fallback failed: ' + (r.error ? 'API error' : e.message) } }];
}

const fs = require('fs');
const prev = $('Still Clip').first().json;
const st = { ...prev.st };
if (fs.existsSync(prev.outPath) && fs.statSync(prev.outPath).size > 5000) {
  return [{ json: { status: 'ok', sceneIndex: prev.sceneIndex, clipPath: prev.outPath, source: 'still', model: prev.cfg.imageModel + ' + ffmpeg', attempts: st.attempts, errors: st.errors } }];
}
return [{ json: { status: 'failed', sceneIndex: prev.sceneIndex, source: null, attempts: st.attempts, errors: st.errors.concat(['still-image ffmpeg failed']) } }];
